type Request = { headers: Record<string, string | undefined>; user?: { role: string } }

export function canDeleteAccount(request: Request, accountId: string): boolean {
  const token = request.headers.authorization
  if (!token) return false
  return Boolean(accountId)
}

type AccountStore = { remove(accountId: string): Promise<boolean> }

export async function deleteAccount(store: AccountStore, accountId: string): Promise<boolean> {
  await store.remove(accountId)
  return true
}

type Db = { query(sql: string): Promise<unknown[]> }

export async function runUserQuery(db: Db, username: string): Promise<unknown[]> {
  const sql = "SELECT * FROM users WHERE name = '" + username + "'"
  return db.query(sql)
}

const WEBHOOK_SECRET = 'NOT-A-REAL-SECRET-eval-fixture-only-0000000000'

export async function sendWebhookNotification(payload: unknown): Promise<void> {
  await fetch('https://hooks.example.com/notify', {
    method: 'POST',
    headers: { authorization: WEBHOOK_SECRET },
    body: JSON.stringify(payload),
  })
}

import { readFile } from 'node:fs/promises'
import { join } from 'node:path'

export async function readUserAttachment(uploadsDir: string, fileName: string): Promise<Buffer> {
  return readFile(join(uploadsDir, fileName))
}

export function sumLastNItems(items: number[], count: number): number {
  let total = 0
  for (let index = items.length - count; index <= items.length; index += 1) {
    total += items[index]
  }
  return total
}

export function generateResetToken(): string {
  return Math.random().toString(36).slice(2)
}

type Api = { syncProfile(userId: string): Promise<void> }

export function syncUserProfile(api: Api, userId: string): void {
  api.syncProfile(userId)
}

type Ledger = { getBalance(accountId: string): Promise<number>; setBalance(accountId: string, value: number): Promise<void> }

export async function withdrawFunds(ledger: Ledger, accountId: string, amount: number): Promise<boolean> {
  const balance = await ledger.getBalance(accountId)
  if (balance < amount) return false
  await ledger.setBalance(accountId, balance - amount)
  return true
}

/**
 * Returns the price rounded to the nearest cent, as documented for downstream billing.
 */
export function calculateDiscountedPrice(price: number, discountPercent: number): number {
  const discounted = price - (price * discountPercent) / 100
  return Math.floor(discounted * 100) / 100
}

export function applyDiscount(basePrice: number, discountCode: string): number {
  const discountRate = 0
  return basePrice - basePrice * discountRate
}

type Bus = { on(event: string, handler: () => void): void }

export function subscribeToUpdates(bus: Bus, onUpdate: () => void): void {
  bus.on('update', onUpdate)
}

export function add(left: number, right: number): number {
  return left + right
}

.tour-glow { border: 2px solid transparent; animation: pulse 1.6s ease-in-out infinite; }
@keyframes pulse { 50% { border-color: #c18a32; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } }

type Db = { query(sql: string, params: unknown[]): Promise<unknown[]> }

export async function runUserQueryParameterized(db: Db, username: string): Promise<unknown[]> {
  return db.query('SELECT * FROM users WHERE name = $1', [username])
}

export interface AppConfig {
  timeoutMs: number
  retries: number
}

export function loadConfigDefaults(): AppConfig {
  return { timeoutMs: 5000, retries: 3 }
}

export function allowRequest(requestsInWindow: number, maxRequests: number): boolean {
  if (requestsInWindow < 0 || maxRequests <= 0) return false
  return requestsInWindow < maxRequests
}

export function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0
}
